(334, 'SENTIMENT_ANALYSIS.38', 'Sentiment Analysis', 'Automatically categorize feedback into positive, neutral, or negative sentiment buckets.', NULL, NULL, 'business', NULL, 38, NULL, 'quality', 'medium', 1, 0, 0, 'new_reviews_only', 96.00, 0, '{\"logic\":\"OR\",\"conditions\":[{\"source\":\"Comment\",\"type\":\"sentiment\",\"operator\":\"equals\",\"value\":\"positive\"},{\"source\":\"Comment\",\"type\":\"sentiment\",\"operator\":\"equals\",\"value\":\"neutral\"},{\"source\":\"Comment\",\"type\":\"sentiment\",\"operator\":\"equals\",\"value\":\"negative\"}]}', '{\"tag\":\"sentiment_categorized\",\"icon\":\"sentiment_satisfied\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'daily', 7, 'staff', '2026-05-17 01:00:06', '2026-05-18 01:00:00', 'system', 1, 1, '2026-02-24 12:55:46', '2026-05-17 01:00:06'),
(335, 'EMOTION_INTENSITY.38', 'Emotion Intensity Detection', 'Identify the strength of emotions like joy, frustration, or anger within text reviews.', NULL, NULL, 'business', NULL, 38, NULL, 'quality', 'medium', 1, 0, 0, 'new_reviews_only', 91.00, 0, '{\"logic\":\"AND\",\"conditions\":[{\"source\":\"Emotion\",\"type\":\"intensity\",\"operator\":\"greater_than\",\"value\":0.6999999999999999555910790149937383830547332763671875}]}', '{\"tag\":\"high_emotion_intensity\",\"icon\":\"mood\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'daily', 7, 'staff', '2026-05-17 01:00:06', '2026-05-18 01:00:00', 'system', 1, 1, '2026-02-24 12:55:46', '2026-05-17 01:00:06'),
(336, 'RATING_COMMENT_MISMATCH.38', 'Rating & Comment Mismatch', 'Detect when a high numerical rating is paired with a negative written review.', NULL, NULL, 'business', NULL, 38, NULL, 'trend', 'high', 1, 0, 0, 'new_reviews_only', 88.00, 0, '{\"logic\":\"AND\",\"conditions\":[{\"source\":\"Rating\",\"type\":\"rating\",\"operator\":\"greater_than\",\"value\":3},{\"source\":\"Comment\",\"type\":\"sentiment\",\"operator\":\"equals\",\"value\":\"negative\"}]}', '{\"tag\":\"mismatch_detected\",\"alert\":true,\"icon\":\"match_word\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'daily', 7, 'staff', '2026-05-17 01:00:06', '2026-05-18 01:00:00', 'system', 1, 1, '2026-02-24 12:55:46', '2026-05-17 01:00:06'),
(337, 'CATEGORY_ISSUE_DETECTION.38', 'Category Issue Detection', 'Sort feedback into predefined categories like Pricing, Quality, or Delivery.', NULL, NULL, 'business', NULL, 38, NULL, 'trend', 'medium', 1, 0, 0, 'new_reviews_only', 85.00, 0, '{\"logic\":\"OR\",\"conditions\":[{\"source\":\"Comment\",\"type\":\"keyword\",\"operator\":\"contains\",\"value\":\"price\"},{\"source\":\"Comment\",\"type\":\"keyword\",\"operator\":\"contains\",\"value\":\"quality\"},{\"source\":\"Comment\",\"type\":\"keyword\",\"operator\":\"contains\",\"value\":\"delivery\"}]}', '{\"tag\":\"category_assigned\",\"icon\":\"category\"}', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'daily', 7, 'staff', '2026-05-17 01:00:06', '2026-05-18 01:00:00', 'system', 1, 1, '2026-02-24 12:55:46', '2026-05-17 01:00:06'),
